create extension if not exists pgcrypto;
create type public.profile_role as enum ('admin','manager','analyst','sales','client');
create type public.lead_status as enum ('new','contacted','qualified','proposal','won','lost');
create type public.lead_priority as enum ('low','medium','high');
create type public.task_status as enum ('pending','completed','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.profile_role not null default 'client',client_company_id uuid,created_at timestamptz not null default now());
create table public.companies(id uuid primary key default gen_random_uuid(),name text not null,industry text,website text,email text,phone text,location text default 'Namibia',notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contacts(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,full_name text not null,job_title text,email text,phone text,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),company_id uuid references public.companies(id) on delete set null,contact_id uuid references public.contacts(id) on delete set null,title text not null,source text not null default 'Manual',status public.lead_status not null default 'new',priority public.lead_priority not null default 'medium',estimated_value numeric(14,2),currency text not null default 'NAD',next_follow_up_at timestamptz,assigned_to uuid references public.profiles(id),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,due_at timestamptz not null,status public.task_status not null default 'pending',related_lead_id uuid references public.leads(id) on delete set null,assigned_to uuid references public.profiles(id),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index companies_name_idx on public.companies(name);create index contacts_company_idx on public.contacts(company_id);create index leads_status_idx on public.leads(status);create index leads_assigned_idx on public.leads(assigned_to);create index tasks_due_idx on public.tasks(due_at) where status='pending';
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'client') on conflict(id) do nothing;return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end;$$;
create trigger companies_updated_at before update on public.companies for each row execute procedure public.set_updated_at();create trigger leads_updated_at before update on public.leads for each row execute procedure public.set_updated_at();
create or replace function public.current_user_role() returns public.profile_role language sql stable security definer set search_path='' as $$ select role from public.profiles where id=(select auth.uid()) $$;
alter table public.profiles enable row level security;alter table public.companies enable row level security;alter table public.contacts enable row level security;alter table public.leads enable row level security;alter table public.tasks enable row level security;
create policy "Users can read own profile" on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy "Admins can manage profiles" on public.profiles for all to authenticated using(public.current_user_role()='admin') with check(public.current_user_role()='admin');
create policy "Staff can manage companies" on public.companies for all to authenticated using(public.current_user_role() in ('admin','manager','analyst','sales')) with check(public.current_user_role() in ('admin','manager','analyst','sales'));
create policy "Staff can manage contacts" on public.contacts for all to authenticated using(public.current_user_role() in ('admin','manager','analyst','sales')) with check(public.current_user_role() in ('admin','manager','analyst','sales'));
create policy "Staff can manage leads" on public.leads for all to authenticated using(public.current_user_role() in ('admin','manager','analyst','sales')) with check(public.current_user_role() in ('admin','manager','analyst','sales'));
create policy "Staff can manage tasks" on public.tasks for all to authenticated using(public.current_user_role() in ('admin','manager','analyst','sales')) with check(public.current_user_role() in ('admin','manager','analyst','sales'));
grant usage on schema public to authenticated;grant select,insert,update,delete on public.profiles,public.companies,public.contacts,public.leads,public.tasks to authenticated;